import json
from pathlib import Path
root=Path(__file__).parent
sources=json.loads((root/'input/source-ledger.json').read_text())
report=json.loads((root/'input/report-ledger.json').read_text())
reg=json.loads((root/'claims.json').read_text())
for item in reg['anchors']:
    item['classification']='non_claim' if item['report_anchor'] in ['P01','P02'] else 'claims'
    item['reason']='Heading or statement of review scope; no domain finding.' if item['classification']=='non_claim' else 'Atomic finding conclusion; all material author premises, citations and steps are audited separately in argument_audit.'
reg['claims']=[]
findings=[]
def ev(name,anchor):
    path='input/sources/'+name+'.md'
    return dict(path=path,anchor=anchor,quote=sources[path][anchor])
L=lambda a:ev('dispatch-ledger',a)
P=lambda a:ev('dispatch-policy',a)
K=lambda a:ev('packet-register',a)
D=lambda a:ev('destination-list',a)
R=lambda a:ev('delivery-records',a)
def proof(theorem,target,relation,explanation):
    return ({'module':'Audit','theorem':'Audit.'+theorem,'target':target,'relation':relation},explanation)
def add(n,question,evidence,rules,reasoning,semantic,outcome,formal,proofs,items,recommendation,limits=(),missing=(),alternatives=(),scope=None,deps=()):
    anchor=f'P{n+2:02}'
    paragraph=report[anchor]
    quote=paragraph.split('** ',1)[1].split(' Argument:',1)[0].split(' Citation:',1)[0].split(' Citations:',1)[0]
    ident=f'F11-{n:02}'
    reg['claims'].append(dict(claim_id=ident,report_anchor=anchor,report_quote=quote,disposition='audited',argument_coverage='Every material supplied justification is separately quoted and assessed in argument_audit.report_items.'))
    ps=[x[0] for x in proofs]
    eis=list(range(len(evidence))); pis=list(range(len(ps)))
    converted=[]
    for kind,text,assessment,why in items:
        assert text in paragraph, (ident,text)
        converted.append(dict(kind=kind,report_anchor=anchor,report_quote=text,assessment=assessment,reasoning=why,evidence_refs=eis,proof_refs=pis))
    citation=paragraph.split('Citation:',1)[-1].strip() if 'Citation:' in paragraph else paragraph.split('Citations:',1)[-1].strip()
    cite_assessment='verified'
    cite_reason='The named supplied passages exist and are reproduced in evidence; their relevance and inferential limits are assessed separately below.'
    if n==3: cite_reason+=' P-02 describes only the ordinary route; the author omitted P-03.'
    if n==6: cite_assessment='contradicted'; cite_reason='L-03 explicitly disclaims approval-timing attestation; the attributed statement is absent and contrary to its stated scope.'
    if n==7: cite_assessment='contradicted'; cite_reason='The supplied K-02 does not contain the claimed confirmation: it lists the annex as not supplied and contains no later observations. This rejects the citation as confirmation by K-02; it does not refute any assertion about the unseen annex contents.'
    if n==8: cite_assessment='unsupported'; cite_reason='The ledger supports checksum success, but P-06 expressly says the rating is undefined and no rating rule is incorporated.'
    if n==9: cite_assessment='verified'; cite_reason='R-01 does contain an attributed acceptance statement; R-02 and R-03 prevent treating it as unambiguous.'
    if n==12: cite_assessment='unsupported'; cite_reason='L-01 limits the ledger to four dispatches and K-03 says the other 36 records are absent; these citations cannot supply a population total.'
    converted.append(dict(kind='citation',report_anchor=anchor,report_quote=citation,assessment=cite_assessment,reasoning=cite_reason,evidence_refs=eis,proof_refs=pis))
    findings.append(dict(claim_id=ident,report_quote=quote,report_anchor=anchor,question=question,evidence=evidence,rules=rules,assumptions=['The supplied synthetic records are faithfully transcribed; source authenticity is outside this audit.'],reasoning=reasoning,semantic_state=semantic,argument_status={'invalid':'invalid_inference','insufficient':'insufficient_support','not_provided':'insufficient_support'}.get(outcome,outcome),formal_status=formal,proofs=ps,limits=['The result is scoped to the supplied synthetic packet and declared policy.']+list(limits),recommendation=recommendation,criteria=dict(origin='inferred',operational_question=question,decision_criteria=rules,scope=scope or 'Exactly dispatches A, B, C and D through end of campaign day 20; integer campaign days and euro cents under DP-7 and DL-7.',missing_definitions=list(missing),alternatives=list(alternatives)),argument_audit=dict(outcome=outcome,report_items=converted,independent_reasoning=reasoning,evidence_refs=eis,proof_refs=pis,claim_dependencies=list(deps)),formalization=dict(rationale=('Small finite source-linked model checks arithmetic, rule applications or a precisely limited auxiliary target; statements of unavailable events remain unconstrained.' if ps else 'No well-defined operational rating predicate or adopted rubric exists. A proof would require inventing a rule, so formalization is blocked.'),correspondence=[dict(proof_ref=i,explanation=x[1]) for i,x in enumerate(proofs)]),support_search=dict(scope='Read every paragraph and table in all five supplied source documents, including cited passages and counterevidence.',queries=[],inspected=[dict(path=p,anchor=a) for p,segments in sources.items() if p.startswith('input/sources/') for a in segments],limitations=['No external evidence, unavailable reliability annex, missing 36 population records, or unprovided rating rubric was inspected.'],conclusion=' '.join(reasoning))))
add(1,'Does the complete four-dispatch cohort sum to 50000 cents?',[L('P02'),L('P03'),L('P04'),P('P06')],['Sum each of the exactly four cohort amounts once.'],['L-01 defines A–D as the complete reviewed cohort; L-02 records 12000, 18000, 9000 and 11000 cents.','The sum is 50000; both the author operands and computation are correct.'],'supported','sufficient','proved',[proof('expenditure','Audit.total = 50000','supports','Audit.cohort contains the four L-02 rows exactly once and total sums their Int amounts; the target is the original cohort total, assuming faithful transcription.')],[('premise','12000 + 18000 + 9000 + 11000','verified','All four operands agree with L-02.'),('inference','12000 + 18000 + 9000 + 11000 = 50000.','verified','The exact integer sum is checked independently.')],'Retain the finding and its cohort limitation.')
add(2,'Is the cohort budget less cohort expenditure equal to 6000 cents?',[L('P02'),L('P04'),P('P06')],['P-05 defines balance as 55000 minus the four-dispatch sum.'],['The source budget is 55000 and the four entries sum to 50000.','55000 - 50000 = 5000, contradicting 6000. The proposed subtraction method is valid but does not yield the reported value.'],'refuted','invalid','refuted',[proof('headroom','Audit.balance = 5000 ∧ Audit.balance ≠ 6000','refutes','Balance uses the 55000 budget from L-01 and the four L-02 amounts with Int subtraction, not truncated natural subtraction; 6000 is directly excluded.')],[('premise','55000-cent comparison budget','verified','L-01 gives exactly this budget.'),('inference','subtract the four dispatch amounts from the 55000-cent comparison budget.','contradicted','This stated operation produces 5000, not the claimed 6000; the inference to that result fails.')],'Replace 6000 with 5000 euro cents.',deps=['F11-01'])
add(3,'Does B fail both available approval routes at cutoff?',[L('P03'),L('P04'),P('P02'),P('P03'),P('P04')],['Ordinary approval requires approval strictly before release.','P-03 also permits R2 releases on days 10–14 with a declaration no more than two days earlier and approval no more than three days later.'],['B release 12 and approval 15 fail the ordinary route.','B is R2, release 12 is within 10–14, declaration 11 is one day before release, and approval 15 is exactly three days later. Every exception conjunct holds.','B has compliant approval, so the report is false. Failure of one route does not imply failure of the alternative.'],'refuted','invalid','refuted',[proof('bApproval','Audit.compliant Audit.b','refutes','The exact claim is noncompliance, so proof of B compliance refutes it. P-02 and P-03 are a disjunction and all B fields come from L-02.'),proof('bException','¬ Audit.ordinary Audit.b ∧ Audit.exception Audit.b','auxiliary','B fails the ordinary timing predicate but satisfies every temporary-exception conjunct; this isolates the author omission.')],[('premise','its approval on day 15 was later than its release on day 12','verified','The ledger records 15 > 12.'),('inference','so it fails the only approval route.','contradicted','P-03 expressly provides a second route, which B satisfies.')],'State that B is compliant through the exception; include P-03.')
add(4,'Does C satisfy every temporary-exception condition?',[L('P03'),L('P04'),P('P03'),P('P04')],['The exception permits approval at most three days after release; no other route beyond ordinary or exception applies.'],['C release 12 and approval 16 have a four-day gap.','C fails the exception upper bound and also fails ordinary prior approval. Its route, release-window and declaration checks do not repair the failed approval deadline.'],'refuted','invalid','refuted',[proof('cApproval','¬ Audit.compliant Audit.c','refutes','With final L-02 approval 16 and release 12, neither P-02 nor P-03 is satisfied; this excludes in particular the claimed exception compliance.'),proof('cDelay','Audit.c.approved - Audit.c.released = 4','auxiliary','The source dates differ by four integer days, directly checking the report arithmetic premise.')],[('premise','approval on day 16 was within three days of release on day 12.','contradicted','16 - 12 equals four, not at most three.'),('inference','approval on day 16 was within three days of release on day 12.','contradicted','The false deadline premise cannot establish exception compliance.')],'State that C is noncompliant at cutoff: approval was four days after release.')
add(5,'Is B eligible under all three P-04 conditions, and is PASS alone sufficient?',[L('P04'),L('P05'),P('P03'),P('P04'),P('P05'),D('P02')],['Eligibility is exactly compliant approval AND PASS checksum AND destination in DL-7.'],['B satisfies the P-03 exception, has PASS, and South belongs to DL-7; independent evidence establishes eligibility.','The author states only PASS is sufficient. D is an in-cohort counterexample: PASS and compliant ordinary approval, but destination East is excluded.','The conclusion is supported while its justification is invalid.'],'supported','invalid','proved',[proof('bEligible','Audit.eligible Audit.b','supports','P-04 is encoded as a conjunction; B approval, checksum and South membership are independently verified from L-02, P-03 and D-01.'),proof('passInsufficient','Audit.d ∈ Audit.cohort ∧ Audit.d.passed = true ∧ ¬ Audit.eligible Audit.d','auxiliary','D is an actual reviewed dispatch with PASS and excluded East destination, refuting PASS-implies-eligible without refuting B eligibility.')],[('premise','its checksum is PASS','verified','L-02 records B PASS.'),('inference','a PASS checksum alone is sufficient for settlement eligibility.','contradicted','P-04 explicitly requires three separate conditions; D witnesses failure of this inference.')],'Retain B eligibility but replace the checksum-only argument with all three conditions.',deps=['F11-03'])
add(6,'Does L-03 contain the attributed assertion that all four approvals preceded release?',[L('P05'),L('P04'),P('P03')],['An attribution claim must match the cited passage; integrity checks cannot be rewritten as timing attestations.'],['L-03 describes byte-checksum equality and explicitly says it does not attest approval timing.','The attributed statement is therefore documentarily refuted. Separately, B and C approval days occur after release; the universal timing event claim would also be false.','The formal counterexample concerns event timing only; it does not mechanize natural-language attribution.'],'refuted','invalid','auxiliary',[proof('notAllPrior','¬ (∀ x ∈ Audit.cohort, Audit.ordinary x)','auxiliary','The finite L-02 rows refute universal prior approval; this corroborates but does not itself prove the distinct textual claim about what L-03 says.')],[],'Replace the attribution with L-03 actual integrity-only scope.',limits=['No Lean theorem claims to interpret natural-language statements or certify a textual attribution.'])
add(7,'Do supplied observations establish zero B reliability incidents on days 21–50?',[K('P02'),K('P03'),L('P05')],['No-event claims require observations or a justified completeness rule for the named future period; attachment inventory is not event history.'],['The primary packet stops at day 20; K-02 explicitly lists the reliability annex as not supplied and contains no later observations.','No supplied passage supports either zero or nonzero later incidents. The claim about what the unseen annex confirms is unsupported because its contents are unavailable. K-02 itself contains no confirmation; the underlying zero-incident proposition remains undetermined.','Two extensions preserve all supplied cohort facts while assigning zero or one later incident; neither is asserted as actual history.'],'undetermined','insufficient','auxiliary',[proof('laterNonentailment','Audit.compatible Audit.quiet ∧ Audit.compatible Audit.incident ∧ Audit.quiet.laterIncidents = 0 ∧ Audit.incident.laterIncidents ≠ 0','auxiliary','K-02 imposes no constraint on later incident count. quiet and incident carry the same 36 unobserved dispatch positions and fixed cohort while differing only in 0 versus 1 later B incidents. The witness shows non-entailment in the declared projection, not actual incident occurrence.')],[('premise','the listed reliability annex confirms the absence of incidents.','unsupported','The annex is not supplied, so its contents cannot be checked. Listing it provides no observations and neither verifies nor refutes what that unseen annex might say.'),('inference','the listed reliability annex confirms the absence of incidents.','unsupported','Neither absence nor presence of incidents follows from K-02.')],'Mark the later incident count unresolved and obtain the actual days 21–50 annex.',limits=['A zero/one model witness is a logical extension, not an observation.'],scope='B reliability during days 21–50, after the day-20 evidence cutoff.')
add(8,'Is there an applicable definition permitting an operationally robust rating?',[L('P04'),L('P05'),P('P07'),K('P04')],['A qualitative rating needs an explicit definition or adopted rubric; checksum success alone supplies only integrity evidence.'],['Every checksum is PASS.','P-06 supplies no definition of operationally robust and no incorporated rating standard; K-03 confirms no further rubric.','The rating cannot be evaluated as a well-defined predicate. This is an unresolved criterion and support gap, not proof that the cohort lacks operational robustness.'],'undetermined','nonformal','blocked',[],[('premise','every checksum passed.','verified','All four L-02 checksum entries are PASS.'),('inference','every checksum passed.','nonformal','No supplied rule connects this true premise to the undefined qualitative rating.')],'Request an operational rating definition, thresholds and evidence requirements before assigning the rating.',missing=['Operationally robust: dimensions, thresholds, aggregation and treatment of missing evidence are undefined.'])
add(9,'Does the whole supplied packet unambiguously establish B physical acceptance at end of day 12?',[R('P02'),R('P03'),R('P04'),P('P05')],['Preserve attributed testimony; compare the same event and instant, and apply only a supplied precedence or reconciliation rule.'],['R-01 records acceptance; R-02 records rejection and explicitly denies acceptance at the same instant.','R-03 grants equal standing and supplies no correction or precedence. The report premise about R-01 is correct but does not settle the opposing record.','The exact unambiguous-establishment claim is refuted by the unresolved contradiction. Actual acceptance remains undetermined/conflicting; neither register is promoted to world truth.'],'refuted','disputed','auxiliary',[proof('recordConflict','Audit.saysAccepted Audit.Record.receiving = true ∧ Audit.saysAccepted Audit.Record.incident = false','auxiliary','The two Bool values represent what R-01 and R-02 state, not two simultaneous event facts. The theorem preserves their opposite attributed polarities; documentary reasoning with R-03 refutes unambiguity.')],[('premise','the signed receiving register records acceptance.','verified','R-01 does record acceptance, attributed to that register.'),('inference','the signed receiving register records acceptance.','disputed','R-02 at equal standing contradicts R-01, so the one cited record cannot establish unambiguous acceptance.')],'State that acceptance is disputed and seek reconciliation or an adjudication.',limits=['The exact claim about unambiguity is refuted; the event proposition is not classified as false.'],alternatives=['If the claim were only that R-01 records acceptance, it would be supported; it instead says supplied evidence unambiguously establishes the event.'],scope='Physical delivery of B at the end of day 12; separate from approval and settlement.')
add(10,'Does day 15 belong to the inclusive release interval from day 10 through day 14?',[P('P02'),P('P04')],['Temporary-exception release days must satisfy 10 ≤ day ≤ 14.'],['The policy makes both endpoints inclusive.','Day 15 exceeds upper endpoint 14, so the claimed interval membership is false.'],'refuted','invalid','refuted',[proof('releaseWindow','¬ Audit.window 15','refutes','Audit.window uses exactly the integer bounds 10 and 14 from P-03; the negative target excludes day 15.')],[],'Correct the exception release window to days 10–14 inclusive.',scope='A release on day 15 under DP-7 temporary exception; no specific dispatch is required.')
add(11,'Does the P-04 eligible subset of A–D have amount 39000 cents?',[L('P02'),L('P03'),L('P04'),P('P03'),P('P04'),P('P05'),P('P06'),D('P02')],['Select precisely cohort members satisfying approval, PASS and DL-7 membership, then sum their amounts.'],['A has prior approval, PASS and North; B has exception approval, PASS and South. Both are eligible.','C fails approval timing; D has destination East outside DL-7. They are ineligible.','Only A and B contribute: 12000 + 18000 = 30000, not 39000. The author incorrectly included C; summing A+B+C is arithmetically 39000 but the membership premise fails.'],'refuted','invalid','refuted',[proof('settlement','Audit.eligibleTotal = 30000 ∧ Audit.eligibleTotal ≠ 39000','refutes','eligibleTotal filters the exact A–D list with the P-04 conjunction and sums Int amounts; source finality and exhaustive approval routes justify excluding C and D.'),proof('eligibleMembers','Audit.eligible Audit.a ∧ Audit.eligible Audit.b ∧ ¬ Audit.eligible Audit.c ∧ ¬ Audit.eligible Audit.d','auxiliary','Individual membership checks map each L-02 row through P-02/P-03, P-04 and D-01; C deadline failure and D destination exclusion explain the correction.')],[('premise','A, B, and C are eligible','contradicted','A and B satisfy P-04, but C approval delay is four days.'),('inference','so add their amounts.','unsupported','Summation is correct only after correct eligibility selection; inclusion of C invalidates this sum as eligible amount.')],'Correct eligible settlement amount to 30000 cents and eligible members to A and B.',deps=['F11-04','F11-05'])
add(12,'Do four supplied rows establish the aggregate amount of all 40 dispatches?',[L('P02'),L('P04'),K('P04'),P('P02')],['A population aggregate needs all population amounts or a valid supplied derivation; four cohort rows establish only their own sum.'],['L-01 identifies 40 campaign dispatches but gives records for exactly four; those four sum to 50000.','K-03 supplies no amounts for the remaining 36 and no extrapolation method. Neither the claimed full total nor its negation is established.','Two extensions contain exactly 36 missing amounts, all zero versus one amount equal to one cent and 35 zero; both preserve the supplied packet while giving different population totals. No rule in the packet requires strictly positive amounts.'],'undetermined','insufficient','auxiliary',[proof('populationNonentailment','Audit.compatible Audit.quiet ∧ Audit.compatible Audit.extraAmount ∧ Audit.populationTotal Audit.quiet = 50000 ∧ Audit.populationTotal Audit.extraAmount ≠ 50000','auxiliary','L-01 fixes 36 additional dispatches and P-01 integer-cent units, but supplies no amount constraints. Both lists have length 36; zero versus one extra cent yields 50000 versus 50001. These logical extensions prove non-entailment of either exact population conclusion in the declared source projection.')],[('premise','the four ledger rows sum to that amount.','verified','The cohort sum is exactly 50000.'),('inference','the four ledger rows sum to that amount.','unsupported','A correct four-row aggregate cannot establish a forty-dispatch total when 36 amounts are unavailable.')],'State only the 50000-cent cohort total and obtain the other 36 dispatch amounts.',limits=['The witness does not assume missing amounts are actually zero or one cent.'],scope='All 40 campaign dispatches; unlike F11-01 this expressly extends beyond reviewed cohort.',deps=['F11-01'])
(root/'claims.json').write_text(json.dumps(reg,indent=2)+'\n')
(root/'findings.json').write_text(json.dumps(findings,indent=2,ensure_ascii=False)+'\n')
print('Wrote',len(findings),'findings')
